import React, { useEffect, useState } from "react";
import { useLocation } from "react-router-dom";
import Header from "../components/header";
import Footer from "../components/footer";
import "./Results.css";

const Results = () => {
  const location = useLocation();
  const query = location.state?.query || "";

  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [favorites, setFavorites] = useState([]);
  const [user, setUser] = useState(null);

  // ================= USER LOAD =================
  useEffect(() => {
    const storedUser = JSON.parse(localStorage.getItem("user"));
    setUser(storedUser);
  }, []);

  // ================= FAVORITES LOAD =================
  useEffect(() => {
    if (!user) return;

    fetch(`http://localhost:5000/favorites/${user.email}`)
      .then((res) => res.json())
      .then((data) => {
        setFavorites(data);

        localStorage.setItem(
          `favorites_${user.email}`,
          JSON.stringify(data)
        );
      })
      .catch((err) => console.log(err));

  }, [user]);

  // ================= FETCH PRODUCTS =================
  useEffect(() => {
    const fetchData = async () => {
      if (!query) {
        setLoading(false);
        return;
      }

      try {
        const response = await fetch(
          `http://localhost:5000/api/search?q=${query}`
        );

        const data = await response.json();

        const results =
          data?.shopping_results ||
          data?.organic_results ||
          data?.inline_shopping_results ||
          [];

        const formatted = results.slice(0, 40).map((item) => ({
          title: item.title || "No Title",
          price: item.price || "N/A",
          rating: item.rating || "3.5",

          // ✅ IMAGE FIX (IMPORTANT)
          image: item.thumbnail || item.image || "",

          // ✅ LINK FIX (IMPORTANT)
          link:
            item.product_link ||
            item.link ||
            item.offer_link ||
            item.source_link ||
            "#",

          source: item.source || "Unknown",
        }));

        setProducts(formatted);

      } catch (error) {
        console.log("ERROR:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [query]);

  // ================= FAVORITE CHECK =================
  const isFavorite = (product) => {
    return favorites.some((item) => item.link === product.link);
  };

  // ================= TOAST =================
  const showToast = (message) => {
    const toast = document.createElement("div");
    toast.innerText = message;
    toast.className = "toast";
    document.body.appendChild(toast);
    setTimeout(() => toast.remove(), 2000);
  };

  // ================= FAVORITES =================
  const toggleFavorite = async (product) => {
    if (!user) {
      showToast("⚠️ Please Sign In / Sign Up first!");
      return;
    }

    try {
      const existing = favorites.find(
        (item) => item.link === product.link
      );

      if (existing) {
        await fetch(
          `http://localhost:5000/favorites/${existing._id}`,
          { method: "DELETE" }
        );

        const updated = favorites.filter(
          (item) => item.link !== product.link
        );

        setFavorites(updated);

        localStorage.setItem(
          `favorites_${user.email}`,
          JSON.stringify(updated)
        );

        showToast("Removed from favorites ❌");

      } else {
        await fetch("http://localhost:5000/favorites", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            userEmail: user.email,
            title: product.title,
            price: product.price,
            rating: product.rating,
            image: product.image,
            link: product.link,
            source: product.source,
          }),
        });

        const updated = [...favorites, product];
        setFavorites(updated);

        localStorage.setItem(
          `favorites_${user.email}`,
          JSON.stringify(updated)
        );

        showToast("Added to favorites ⭐");
      }

    } catch (error) {
      console.log(error);
    }
  };

  return (
    <>
      <Header />

      <div style={{ padding: "20px" }}>
        <h2>Results</h2>
        <p>Search: {query}</p>

        {loading ? (
          <p>Loading...</p>
        ) : products.length === 0 ? (
          <p>No products found</p>
        ) : (
          <div className="products-grid">

            {products.map((item, index) => (
              <div className="product-card" key={index}>

                {/* ================= IMAGE FIX ================= */}
                {item.image ? (
                  <img
                    src={item.image}
                    alt={item.title}
                    className="product-img"
                  />
                ) : (
                  <div
                    style={{
                      height: "150px",
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      opacity: 0.5,
                    }}
                  >
                    🛍️
                  </div>
                )}

                <h3 className="product-title">{item.title}</h3>

                <p><b>Price:</b> {item.price}</p>
                <p><b>Rating:</b> {item.rating}</p>
                <p><b>Source:</b> {item.source}</p>

                <div className="btn-group">

                  {/* ⭐ FAVORITE */}
                  <button
                    className="star-btn"
                    onClick={() => toggleFavorite(item)}
                  >
                    {isFavorite(item) ? "★" : "☆"}
                  </button>

                  {/* ================= WEBSITE FIX ================= */}
                  <button
                    onClick={() => {
                      if (item.link && item.link !== "#") {
                        window.open(item.link, "_blank"); // ✅ FIXED (friend logic)
                      } else {
                        alert("Link not available");
                      }
                    }}
                  >
                    Go to Website
                  </button>

                </div>

              </div>
            ))}

          </div>
        )}
      </div>

      <Footer />
    </>
  );
};

export default Results;
